## My answer to the prompt

Assuming an input is valid when it exactly matches an option, this component filters by prefix, limits the number of rendered suggestions, supports keyboard selection, and keeps the input visible when there are no matches. For very large datasets, limiting rendered results helps the DOM; filtering still scans the options, so a precomputed index, worker, or server-side search may be appropriate at larger scales.

```tsx
import { useMemo, useState } from "react";

type InputProps = {
  options: string[];
  onChange?: (value: string) => void;
  maxSuggestions?: number;
};

export function Input({
  options,
  onChange,
  maxSuggestions = 50,
}: InputProps) {
  const [value, setValue] = useState("");
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);

  const suggestions = useMemo(() => {
    const query = value.trim().toLocaleLowerCase();
    if (!query) return [];

    const matches: string[] = [];
    for (const option of options) {
      if (option.toLocaleLowerCase().startsWith(query)) {
        matches.push(option);
        if (matches.length === maxSuggestions) break;
      }
    }
    return matches;
  }, [options, value, maxSuggestions]);

  const valid =
    value.trim() === "" ||
    options.some(
      option => option.toLocaleLowerCase() === value.trim().toLocaleLowerCase()
    );

  function choose(option: string) {
    setValue(option);
    onChange?.(option);
    setOpen(false);
    setActive(-1);
  }

  return (
    <div>
      <input
        role="combobox"
        aria-expanded={open && suggestions.length > 0}
        aria-autocomplete="list"
        value={value}
        onFocus={() => setOpen(true)}
        onChange={event => {
          setValue(event.target.value);
          onChange?.(event.target.value);
          setActive(-1);
          setOpen(true);
        }}
        onKeyDown={event => {
          if (event.key === "Escape") setOpen(false);
          if (!suggestions.length) return;

          if (event.key === "ArrowDown") {
            event.preventDefault();
            setActive(i => (i + 1) % suggestions.length);
          } else if (event.key === "ArrowUp") {
            event.preventDefault();
            setActive(i => (i <= 0 ? suggestions.length - 1 : i - 1));
          } else if (event.key === "Enter" && active >= 0) {
            event.preventDefault();
            choose(suggestions[active]);
          }
        }}
        style={{ border: `1px solid ${valid ? "#888" : "red"}` }}
      />

      {open && suggestions.length > 0 && (
        <ul role="listbox">
          {suggestions.map((option, index) => (
            <li
              key={`${option}-${index}`}
              role="option"
              aria-selected={index === active}
              onMouseDown={event => event.preventDefault()}
              onClick={() => choose(option)}
            >
              {option}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
```

## Evaluation

